package com.nigson.commerce.notification;

import java.net.*;
import java.net.http.*;
import java.time.Duration;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.Flow;
import java.nio.ByteBuffer;
import java.util.function.Function;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import com.nigson.commerce.security.*;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.*;

/** Commerce-owned session and signed-actor relay for API-192. */
public final class StaffReplyRelay {
    private static final PrivateWorkload.Route CONTEXT=route("API-194");
    private static final PrivateWorkload.Route COMMAND=route("API-193");
    private static final tools.jackson.databind.json.JsonMapper JSON=tools.jackson.databind.json.JsonMapper.builder(tools.jackson.core.json.JsonFactory.builder().enable(tools.jackson.core.StreamReadFeature.STRICT_DUPLICATE_DETECTION).streamReadConstraints(tools.jackson.core.StreamReadConstraints.builder().maxNestingDepth(8).maxStringLength(4096).maxNumberLength(20).build()).build()).enable(tools.jackson.databind.DeserializationFeature.FAIL_ON_TRAILING_TOKENS).build();
    private final URI base;private final HttpClient http;private final Function<PrivateWorkload.Route,String> credentials;private final ActorDelegation delegation;private final JdbcSessionTrust sessions;private final CommerceAuthority authority;
    public StaffReplyRelay(String env,String endpoint,Function<PrivateWorkload.Route,String> credentials,ActorDelegation delegation,JdbcSessionTrust sessions,CommerceAuthority authority){this.base=target(env,endpoint);this.credentials=Objects.requireNonNull(credentials);this.delegation=Objects.requireNonNull(delegation);this.sessions=Objects.requireNonNull(sessions);this.authority=Objects.requireNonNull(authority);http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(2)).followRedirects(HttpClient.Redirect.NEVER).build();}
    public static URI target(String env,String endpoint){try{if(!Set.of("local","test","dev","qa","stage","prod").contains(env)||endpoint==null||endpoint.length()>2048)throw new IllegalArgumentException();var uri=URI.create(endpoint);boolean local=Set.of("local","test").contains(env);if(uri.getHost()==null||uri.getUserInfo()!=null||uri.getRawQuery()!=null||uri.getFragment()!=null||!Set.of("","/").contains(uri.getRawPath())||!(local?"http".equals(uri.getScheme())&&Set.of("127.0.0.1","localhost","integration").contains(uri.getHost()):"https".equals(uri.getScheme())&&uri.getHost().matches("[a-z0-9]+(?:[.-][a-z0-9]+)*\\.internal")&&uri.getPort()==-1))throw new IllegalArgumentException();return URI.create(uri.getScheme()+"://"+uri.getRawAuthority());}catch(RuntimeException bad){throw new IllegalArgumentException("INTEGRATION_TARGET_REQUIRED");}}
    public StaffReplyValues.Acknowledgement send(ActorAssertion.Actor actor,String session,StaffReplyValues.Command command,UUID correlation){outside();current(actor,session);if(command==null||correlation==null||correlation.equals(new UUID(0,0)))throw ApiValues.invalid();String getPath=CONTEXT.path().replace("{id}",command.leadId().toString());byte[] body=EventCodec.JSON.writeValueAsBytes(Map.of("commandId",command.commandId().toString(),"leadId",command.leadId().toString(),"templateCode",command.templateCode(),"channel",command.channel(),"variables",new TreeMap<>(command.variables())));if(body.length>8192)throw ApiValues.invalid();String contextActor,commandActor,token;try{contextActor=delegation.issue(session,new ActorAssertion.Binding("experience",CONTEXT.scope(),"GET",getPath,correlation,ActorAssertion.Binding.bodyHash(new byte[0])),null);commandActor=delegation.issue(session,new ActorAssertion.Binding("integration",COMMAND.scope(),"POST",COMMAND.path(),correlation,ActorAssertion.Binding.bodyHash(body)),null);token=credentials.apply(COMMAND);}catch(org.springframework.security.access.AccessDeniedException denied){throw new Problem.Failure(ProblemCode.ACCESS_DENIED);}catch(RuntimeException unavailable){throw new Problem.Failure(ProblemCode.PROVIDER_UNAVAILABLE);}if(token==null||!token.matches("[A-Za-z0-9._~+/-]{1,16384}={0,2}"))throw new Problem.Failure(ProblemCode.PROVIDER_UNAVAILABLE);
        var request=HttpRequest.newBuilder(base.resolve(COMMAND.path())).timeout(Duration.ofSeconds(6)).header("Authorization","Bearer "+token).header("X-Nigson-Actor",commandActor).header("X-Nigson-Context-Actor",contextActor).header("X-Correlation-ID",correlation.toString()).header("Idempotency-Key",command.commandId().toString()).header("Content-Type","application/json").header("Accept","application/json").POST(HttpRequest.BodyPublishers.ofByteArray(body)).build();CompletableFuture<HttpResponse<byte[]>> future=null;try{future=http.sendAsync(request,info->new Limited());var response=future.get(7,TimeUnit.SECONDS);current(actor,session);if(response.headers().allValues("Content-Type").size()!=1)throw unknown();String type=response.headers().firstValue("Content-Type").orElse("").split(";",2)[0].strip();var json=JSON.readTree(response.body());if(response.statusCode()!=202){for(var code:List.of(ProblemCode.VALIDATION_ERROR,ProblemCode.AUTH_REQUIRED,ProblemCode.ACCESS_DENIED,ProblemCode.NOT_FOUND,ProblemCode.IDEMPOTENCY_HASH_MISMATCH,ProblemCode.NOTIFICATION_RULE_VIOLATION,ProblemCode.FEATURE_DISABLED))if(response.statusCode()==code.status&&"application/problem+json".equals(type)&&code.name().equals(json.path("code").asString()))throw new Problem.Failure(code);throw unknown();}if(!"application/json".equals(type)||!json.isObject()||!json.propertyNames().equals(Set.of("jobId","state"))||!command.commandId().toString().equals(json.path("jobId").asString())||!"PENDING".equals(json.path("state").asString()))throw unknown();return new StaffReplyValues.Acknowledgement(command.commandId(),"PENDING");}catch(Problem.Failure failure){throw failure;}catch(Exception failure){if(failure instanceof InterruptedException)Thread.currentThread().interrupt();throw unknown();}finally{if(future!=null&&!future.isDone())future.cancel(true);}}
    private void current(ActorAssertion.Actor actor,String session){var fresh=authority.resolve(sessions.read(session,true),null,Set.of());if(actor==null||!actor.party().equals(fresh.party())||!actor.identityIssuer().equals(fresh.identityIssuer())||!actor.identitySubject().equals(fresh.identitySubject())||!fresh.roles().contains("SALES")||fresh.organization()!=null)throw ActorAssertion.denied();}
    private static PrivateWorkload.Route route(String api){return PrivateWorkload.ROUTES.stream().filter(r->r.api().equals(api)).findFirst().orElseThrow(ActorAssertion::denied);}
    private static void outside(){if(TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("STAFF_REPLY_HTTP_OUTSIDE_TRANSACTION_REQUIRED");}
    private static Problem.Failure unknown(){return new Problem.Failure(ProblemCode.PROVIDER_OUTCOME_UNKNOWN);}
    private static final class Limited implements HttpResponse.BodySubscriber<byte[]>{private final CompletableFuture<byte[]> result=new CompletableFuture<>();private final java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();private Flow.Subscription subscription;public CompletionStage<byte[]> getBody(){return result;}public void onSubscribe(Flow.Subscription value){subscription=value;value.request(1);}public void onNext(List<ByteBuffer> chunks){for(var chunk:chunks){if(bytes.size()+chunk.remaining()>8192){subscription.cancel();result.completeExceptionally(new IllegalArgumentException("BODY_LIMIT"));return;}byte[] part=new byte[chunk.remaining()];chunk.get(part);bytes.writeBytes(part);}subscription.request(1);}public void onError(Throwable failure){result.completeExceptionally(failure);}public void onComplete(){result.complete(bytes.toByteArray());}}
}
